 p=argparse.ArgumentParser();p.add_argument('--evidence-dir',type=Path,required=True);p.add_argument('--output-dir',type=Path,required=True);a=p.parse_args();M=a.evidence_dir/'scaled-mechanism-cases-r01';out=a.output_dir
