 names=['editorial-source-seed-r01.json','editorial-source-selection-r01.json','editorial-target-preferences500-r01.tsv','editorial-target-alternatives500-r01.json.gz','editorial-jmdict-target-records500-r01.json.gz','editorial-japanese-primary-choices500-r01.json','editorial-primary-read-closure-r01.json','editorial-target-primary-request500-r01.json','editorial-target-supplemental-request500-r03.json','editorial-content500-candidate-r01.json','editorial-content500-evaluation-freeze-r01.json','editorial-content500-TRAIN-output-r01.json','editorial-content500-independent96-review-r01.json','editorial-content500-author-review-r01.json','editorial-content500-independent-root-review-r01.json','editorial-content500-joined-decision-r01.json','editorial-target-primary500-r01/selected-native-targets.json.gz','editorial-target-primary500-r02/selected-native-targets.json.gz','editorial-target-primary500-r01/failed-read-r01.json','editorial-target-primary500-r01/isolated-open-failure-r01.json']
 files=[]
 for name in names:
  src=M/name;raw=src.read_bytes();compressed=src.suffix=='.gz';destname=name if compressed or src.suffix=='.tsv' else name+'.gz';dest=out/destname;dest.parent.mkdir(parents=True,exist_ok=True);payload=raw if compressed or src.suffix=='.tsv' else gzip.compress(raw,compresslevel=9,mtime=0);dest.write_bytes(payload)
